{
  "name": "ASCII扫描数据文件",
  "name_en": "ASCII scan data file",
  "manufacturer": "",
  "description": "一种用于实验扫描结果记录的ASCII列式数据文件，采用以“#”开头的注释行和按行分隔的文本格式，结构类似XDI。它通常用于保存步进扫描或EPICS扫描过程中的时间戳、扫描参数、附加过程变量、列标题和数值数据，便于实验数据归档、交换和后续分析。",
  "description_en": "An ASCII column-formatted data file used to record experimental scan results, with line-delimited text and comment lines beginning with '#', in a format derived from XDI. It is typically used to store timestamps, scan parameters, extra process variables, column legends, and numeric data from step scans or EPICS-based scans for archiving, exchange, and later analysis.",
  "tag_hints": [
    "scan data logging",
    "ASCII column file",
    "XDI-like format",
    "EPICS scan",
    "step scan data",
    "experimental metadata",
    "data export"
  ],
  "actions": [
    {
      "action_name": "auto-read",
      "description": "读取ASCII扫描数据文件内容。",
      "description_en": "Read the contents of an ASCII scan data file."
    },
    {
      "action_name": "auto-write_comments",
      "description": "写入注释行。",
      "description_en": "Write comment lines."
    },
    {
      "action_name": "auto-write_data",
      "description": "写入扫描数据区。",
      "description_en": "Write the scan data section."
    },
    {
      "action_name": "auto-write_extrapvs",
      "description": "写入附加过程变量信息。",
      "description_en": "Write extra process variable information."
    },
    {
      "action_name": "auto-write_legend",
      "description": "写入数据列图例或列标题。",
      "description_en": "Write the data column legend or headers."
    },
    {
      "action_name": "auto-write_lines",
      "description": "写入一组文本行。",
      "description_en": "Write an array of text lines."
    },
    {
      "action_name": "auto-write_scanparams",
      "description": "写入扫描参数。",
      "description_en": "Write scan parameters."
    },
    {
      "action_name": "auto-write_timestamp",
      "description": "写入时间戳。",
      "description_en": "Write a timestamp."
    },
    {
      "action_name": "auto-get_data",
      "description": "获取扫描数据内容。",
      "description_en": "Get the scan data content."
    },
    {
      "action_name": "auto-open_for_write",
      "description": "打开文件以供写入。",
      "description_en": "Open the file for writing."
    },
    {
      "action_name": "auto-check_writeable",
      "description": "检查文件是否可写。",
      "description_en": "Check whether the file is writable."
    },
    {
      "action_name": "auto-flush",
      "description": "刷新缓冲区并将内容写入磁盘。",
      "description_en": "Flush buffered content to disk."
    },
    {
      "action_name": "auto-write",
      "description": "写入文本内容。",
      "description_en": "Write text content."
    }
  ]
}

